referenceSolutions.javascript:
export function solve(input) {
  const d = input;
  const clone = (v) => JSON.parse(JSON.stringify(v));
  const original = clone(d.value),
    updated = clone(d.value);
  for (const op of d.operations) {
    if (op.op === "push") updated.push(clone(op.value));
    else if (op.op === "set") updated[op.index] = clone(op.value);
    else updated.splice(op.index, 1);
  }
  return { original, updated };
}

